@php
    $options = $analytics['filter_options'] ?? [];
    $recent = $analytics['recent'] ?? collect();
    $palette = ['#ff6b35', '#2563eb', '#16a34a', '#8b5cf6', '#d97706', '#0891b2', '#dc2626', '#64748b'];
    $formatClp = static fn ($amount) => '$' . number_format((float) $amount, 0, ',', '.');
    $formatQty = static function ($amount): string {
        $amount = (float) $amount;
        return abs($amount - round($amount)) < 0.0001
            ? number_format($amount, 0, ',', '.')
            : number_format($amount, 3, ',', '.');
    };
    $articleDistribution = $analytics['articulos_distribucion'] ?? [];
    $sizeDistribution = $analytics['tallas_distribucion'] ?? [];
    $articleTotal = max(1, array_sum(array_column($articleDistribution, 'netas')));
    $sizeTotal = max(1, array_sum(array_column($sizeDistribution, 'netas')));
    $articleCursor = 0; $articleStops = [];
    foreach ($articleDistribution as $row) { $end = $articleCursor + (($row['netas'] / $articleTotal) * 100); $articleStops[] = $palette[count($articleStops) % count($palette)] . " {$articleCursor}% {$end}%"; $articleCursor = $end; }
    $sizeCursor = 0; $sizeStops = [];
    foreach ($sizeDistribution as $row) { $end = $sizeCursor + (($row['netas'] / $sizeTotal) * 100); $sizeStops[] = $palette[count($sizeStops) % count($palette)] . " {$sizeCursor}% {$end}%"; $sizeCursor = $end; }
    $maxPeople = max([1, ...array_map(fn ($row) => max(0, (float) $row['netas']), $analytics['personas_top'] ?? [])]);
    $maxArticleValue = max([1, ...array_map(fn ($row) => abs((float) $row['valor_neto']), $analytics['articulos'] ?? [])]);
    $recordData = $recent->map(fn ($record) => [
        'reference' => '#' . ($record->entrega->kizeo_record_number ?: $record->entrega->kizeo_data_id),
        'date' => $record->fecha ?: 'Sin fecha',
        'type' => $record->tipo,
        'person' => $record->persona,
        'rut' => $record->rut ?: 'Sin RUT',
        'center' => $record->centro,
        'registeredBy' => $record->registrado_por,
        'delivered' => (float) $record->entregadas,
        'returned' => (float) $record->devueltas,
        'net' => (float) $record->netas,
        'valuedUnits' => (float) $record->unidades_valorizadas,
        'unvaluedUnits' => (float) $record->unidades_sin_precio,
        'referenceValue' => (float) $record->valor_neto,
        'documentUrl' => route('entregas-bodega-dashboard.document', $record->entrega),
        'items' => $record->items->map(fn ($item) => ['article' => $item->articulo, 'size' => $item->talla, 'delivered' => (float) $item->entregadas, 'returned' => (float) $item->devueltas, 'net' => (float) $item->netas, 'referencePrice' => $item->precio_referencia, 'referenceValue' => (float) $item->valor_neto, 'priceSource' => $item->origen_precio])->values(),
    ])->values();
