            <article class="glass-card warehouse-panel warehouse-span-5"><h3><i class="bi bi-person-check-fill"></i> Personas con mayor consumo neto</h3><p class="warehouse-panel-subtitle">Ranking de unidades que permanecen asignadas tras sus devoluciones.</p><div class="warehouse-bars">@forelse($analytics['personas_top'] as $person)<div class="warehouse-bar-row" title="{{ $person['nombre'] }}: {{ $formatQty($person['netas']) }} unidades netas"><div class="warehouse-bar-label">{{ $person['nombre'] }}<div class="warehouse-muted">{{ $person['centro'] }}</div></div><div class="warehouse-bar-track"><span class="warehouse-bar green" style="width:{{ max(0, $person['netas']) / $maxPeople * 100 }}%"></span></div><div class="warehouse-count">{{ $formatQty($person['netas']) }}</div></div>@empty<div class="warehouse-empty">Sin personas identificadas.</div>@endforelse</div></article>
        </section>

        <section class="warehouse-visual-grid" aria-label="Detalle por persona y artículo">
            <article class="glass-card warehouse-panel warehouse-span-8"><h3><i class="bi bi-diagram-3-fill"></i> Persona y centro de costo</h3><p class="warehouse-panel-subtitle">Cruce trazable de persona, centro imputado, entregas, devoluciones y consumo neto.</p><div class="warehouse-table-wrap"><table class="warehouse-table warehouse-relationship-table"><thead><tr><th>Persona</th><th>Centro</th><th class="numeric">Entregado</th><th class="numeric">Devuelto</th><th class="numeric">Neto</th><th class="numeric">Valor neto</th></tr></thead><tbody>@forelse($analytics['relaciones'] as $relation)<tr><td><strong>{{ $relation['nombre'] }}</strong></td><td>{{ $relation['centro'] }}</td><td class="numeric">{{ $formatQty($relation['entregadas']) }}</td><td class="numeric">{{ $formatQty($relation['devueltas']) }}</td><td class="numeric"><span class="warehouse-badge">{{ $formatQty($relation['netas']) }} unid.</span></td><td class="numeric">{{ $formatClp($relation['valor_neto']) }}</td></tr>@empty<tr><td colspan="6" class="warehouse-empty">Sin relaciones para los filtros seleccionados.</td></tr>@endforelse</tbody></table></div></article>
            <article class="glass-card warehouse-panel warehouse-span-4"><h3><i class="bi bi-cash-stack"></i> Artículos por valor neto</h3><p class="warehouse-panel-subtitle">Valor referencial de lo entregado menos lo devuelto.</p><div class="warehouse-bars">@forelse($analytics['articulos'] as $article)<div class="warehouse-bar-row warehouse-item-ranking" title="{{ $article['label'] }}: {{ $formatClp($article['valor_neto']) }}"><div class="warehouse-bar-label">{{ $article['label'] }}<div class="warehouse-muted">{{ $formatQty($article['netas']) }} unid. netas</div></div><div class="warehouse-bar-track"><span class="warehouse-bar orange" style="width:{{ abs($article['valor_neto']) / $maxArticleValue * 100 }}%"></span></div><div class="warehouse-count">{{ $formatClp($article['valor_neto']) }}</div></div>@empty<div class="warehouse-empty">No hay artículos valorizados para mostrar.</div>@endforelse</div></article>
        </section>

        <section class="glass-card warehouse-panel"><h3><i class="bi bi-table"></i> Operaciones aplicadas del período</h3><p class="warehouse-panel-subtitle">Cada fila se construye desde movimientos vigentes de Inventario. Abre el detalle para revisar los ítems netos y el comprobante original de Kizeo.</p><div class="warehouse-table-wrap"><table class="warehouse-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Persona</th><th>Centro imputado</th><th>Resumen EPP</th><th class="numeric">Entregado</th><th class="numeric">Devuelto</th><th class="numeric">Neto</th><th class="numeric">Valor neto</th><th aria-label="Acciones"></th></tr></thead><tbody>@forelse($recent as $record)<tr><td>{{ $record->fecha ? \Carbon\Carbon::parse($record->fecha)->format('d/m/Y') : 'Sin fecha' }}<div class="warehouse-muted">#{{ $record->entrega->kizeo_record_number ?: $record->entrega->kizeo_data_id }}</div></td><td><span class="warehouse-badge {{ $record->tipo === 'Devolución' ? 'return' : '' }}">{{ $record->tipo }}</span></td><td><strong>{{ $record->persona }}</strong><div class="warehouse-muted">{{ $record->rut }}</div></td><td>{{ $record->centro }}</td><td><div class="warehouse-item-summary">@foreach($record->items->take(2) as $item)<div><span class="warehouse-badge">{{ $formatQty($item->netas) }} x {{ $item->articulo }}</span><span class="warehouse-muted">{{ $item->talla }}</span></div>@endforeach @if($record->items->count() > 2)<span class="warehouse-more-items">+{{ $record->items->count() - 2 }} ítem(s) en detalle</span>@endif</div></td><td class="numeric">{{ $formatQty($record->entregadas) }}</td><td class="numeric">{{ $formatQty($record->devueltas) }}</td><td class="numeric"><strong class="warehouse-number {{ $record->netas < 0 ? 'negative' : 'positive' }}">{{ $formatQty($record->netas) }}</strong></td><td class="numeric">{{ $formatClp($record->valor_neto) }}</td><td><div class="warehouse-row-actions"><button type="button" class="warehouse-icon-button" title="Ver detalle neto" aria-label="Ver detalle neto" onclick="openWarehouseDetail({{ $loop->index }})"><i class="bi bi-eye"></i></button><button type="button" class="warehouse-icon-button" title="Ver PDF generado por Kizeo" aria-label="Ver PDF generado por Kizeo" onclick="openWarehouseDocument({{ $loop->index }})"><i class="bi bi-file-earmark-pdf"></i></button></div></td></tr>@empty<tr><td colspan="10" class="warehouse-empty">No hay movimientos aplicados para los filtros seleccionados.</td></tr>@endforelse</tbody></table></div></section>
    @endif
</div>

<div class="warehouse-modal-backdrop" id="warehouse-detail-modal" role="dialog" aria-modal="true" aria-labelledby="warehouse-detail-title" onclick="if(event.target===this)closeWarehouseModal('warehouse-detail-modal')"><section class="warehouse-modal"><header class="warehouse-modal-head"><div><h3 id="warehouse-detail-title"><i class="bi bi-box-seam"></i> Detalle de operación</h3><p id="warehouse-detail-reference"></p></div><button type="button" class="warehouse-icon-button" title="Cerrar detalle" aria-label="Cerrar detalle" onclick="closeWarehouseModal('warehouse-detail-modal')"><i class="bi bi-x-lg"></i></button></header><div class="warehouse-modal-body"><div class="warehouse-detail-grid" id="warehouse-detail-fields"></div><table class="warehouse-detail-table"><thead><tr><th>Artículo EPP</th><th>Talla</th><th>Entregado</th><th>Devuelto</th><th>Neto</th><th>Precio ref.</th><th>Valor neto</th></tr></thead><tbody id="warehouse-detail-items"></tbody></table></div></section></div>
<div class="warehouse-modal-backdrop" id="warehouse-document-modal" role="dialog" aria-modal="true" aria-labelledby="warehouse-document-title" onclick="if(event.target===this)closeWarehouseDocument()"><section class="warehouse-modal document"><header class="warehouse-modal-head"><div><h3 id="warehouse-document-title"><i class="bi bi-file-earmark-pdf"></i> Documento Kizeo</h3><p id="warehouse-document-reference"></p></div><div class="warehouse-row-actions"><a id="warehouse-document-open" class="warehouse-icon-button" target="_blank" rel="noopener" title="Abrir PDF en una nueva pestaña" aria-label="Abrir PDF en una nueva pestaña"><i class="bi bi-box-arrow-up-right"></i></a><button type="button" class="warehouse-icon-button" title="Cerrar visor" aria-label="Cerrar visor" onclick="closeWarehouseDocument()"><i class="bi bi-x-lg"></i></button></div></header><iframe id="warehouse-document-frame" class="warehouse-document-frame" title="Documento generado por Kizeo"></iframe></section></div>
@endsection

@push('scripts')
<script src="{{ asset('vendor/chartjs/chart.umd.js') }}"></script>
<script>
    const warehouseDailyTrend = @json($analytics['by_day'] ?? []);
    const warehouseRecords = @json($recordData);
    const warehouseFormatDate = (value, includeYear = false) => { const [year, month, day] = String(value).split('-').map(Number); return new Intl.DateTimeFormat('es-CL', includeYear ? { day: '2-digit', month: 'short', year: 'numeric' } : { day: '2-digit', month: 'short' }).format(new Date(year, month - 1, day)).replace('.', ''); };
    const warehouseFormatCurrency = (value) => `$${Number(value || 0).toLocaleString('es-CL', { maximumFractionDigits: 0 })}`;
    const warehouseFormatQty = (value) => Number(value || 0).toLocaleString('es-CL', { maximumFractionDigits: 3 });
    const warehouseTrendCanvas = document.getElementById('warehouse-daily-combo-chart');
    if (warehouseTrendCanvas && window.Chart && warehouseDailyTrend.length) {
        const pageStyles = getComputedStyle(document.documentElement); const muted = pageStyles.getPropertyValue('--text-muted').trim() || '#64748b'; const border = pageStyles.getPropertyValue('--border-color').trim() || 'rgba(148, 163, 184, .35)';
        new Chart(warehouseTrendCanvas, { data: { labels: warehouseDailyTrend.map((point) => point.label), datasets: [
            { type: 'bar', label: 'Entregado', data: warehouseDailyTrend.map((point) => point.entregadas), yAxisID: 'units', backgroundColor: '#8b5cf6', borderRadius: 4, borderSkipped: false, barPercentage: .68, categoryPercentage: .82 },
            { type: 'bar', label: 'Devuelto', data: warehouseDailyTrend.map((point) => point.devueltas), yAxisID: 'units', backgroundColor: '#16a34a', borderRadius: 4, borderSkipped: false, barPercentage: .68, categoryPercentage: .82 },
            { type: 'line', label: 'Consumo neto', data: warehouseDailyTrend.map((point) => point.netas), yAxisID: 'units', borderColor: '#ff6b35', backgroundColor: '#ff6b35', borderWidth: 2.5, tension: .28, pointRadius: 3, pointHoverRadius: 5, pointBackgroundColor: '#fff', pointBorderWidth: 2, fill: false },
            { type: 'line', label: 'Valor neto', data: warehouseDailyTrend.map((point) => point.valor_neto), yAxisID: 'value', borderColor: '#2563eb', backgroundColor: '#2563eb', borderWidth: 2.5, tension: .28, pointRadius: 3, pointHoverRadius: 5, pointBackgroundColor: '#fff', pointBorderWidth: 2, fill: false },
        ] }, options: { responsive: true, maintainAspectRatio: false, interaction: { mode: 'index', intersect: false }, plugins: { legend: { position: 'bottom', align: 'start', labels: { color: muted, usePointStyle: true, boxWidth: 8, padding: 16, font: { size: 11 } } }, tooltip: { callbacks: { title: (items) => `Fecha: ${warehouseFormatDate(items[0].label, true)}`, label: (item) => item.dataset.yAxisID === 'value' ? `${item.dataset.label}: ${warehouseFormatCurrency(item.raw)}` : `${item.dataset.label}: ${warehouseFormatQty(item.raw)}` } } }, scales: { x: { grid: { display: false }, ticks: { color: muted, maxRotation: 0, autoSkip: true, maxTicksLimit: 10, callback: (_, index) => warehouseFormatDate(warehouseDailyTrend[index].label) } }, units: { type: 'linear', position: 'left', beginAtZero: true, grid: { color: border }, ticks: { color: muted, precision: 0 }, title: { display: true, text: 'Unidades EPP', color: muted, font: { size: 11, weight: '600' } } }, value: { type: 'linear', position: 'right', beginAtZero: true, grid: { drawOnChartArea: false }, ticks: { color: muted, callback: (value) => warehouseFormatCurrency(value) }, title: { display: true, text: 'Valor neto (CLP)', color: muted, font: { size: 11, weight: '600' } } } } } });
    }
    const warehouseText = (value) => String(value ?? '').replace(/[&<>'"]/g, (character) => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[character]));
    function closeWarehouseModal(id) { document.getElementById(id)?.classList.remove('is-open'); }
    function openWarehouseDetail(index) { const record = warehouseRecords[index]; if (!record) return; document.getElementById('warehouse-detail-reference').textContent = `${record.reference} · ${warehouseFormatDate(record.date, true)}`; document.getElementById('warehouse-detail-fields').innerHTML = [['Tipo', record.type], ['Persona', record.person], ['RUT', record.rut], ['Centro de costo', record.center], ['Entregado', warehouseFormatQty(record.delivered)], ['Devuelto', warehouseFormatQty(record.returned)], ['Consumo neto', warehouseFormatQty(record.net)], ['Valor neto', warehouseFormatCurrency(record.referenceValue)]].map(([label, value]) => `<div class="warehouse-detail-field"><span>${warehouseText(label)}</span><strong>${warehouseText(value)}</strong></div>`).join(''); document.getElementById('warehouse-detail-items').innerHTML = record.items.length ? record.items.map((item) => `<tr><td>${warehouseText(item.article)}</td><td>${warehouseText(item.size)}</td><td>${warehouseText(warehouseFormatQty(item.delivered))}</td><td>${warehouseText(warehouseFormatQty(item.returned))}</td><td>${warehouseText(warehouseFormatQty(item.net))}</td><td>${item.referencePrice === null ? 'Sin precio' : `${warehouseText(warehouseFormatCurrency(item.referencePrice))}<div class="warehouse-muted">${warehouseText(item.priceSource)}</div>`}</td><td>${warehouseText(warehouseFormatCurrency(item.referenceValue))}</td></tr>`).join('') : '<tr><td colspan="7" class="warehouse-muted">No hay ítems aplicados para esta operación.</td></tr>'; document.getElementById('warehouse-detail-modal').classList.add('is-open'); }
    function openWarehouseDocument(index) { const record = warehouseRecords[index]; if (!record) return; document.getElementById('warehouse-document-reference').textContent = `${record.reference} · ${record.person}`; document.getElementById('warehouse-document-open').href = record.documentUrl; document.getElementById('warehouse-document-frame').src = record.documentUrl; document.getElementById('warehouse-document-modal').classList.add('is-open'); }
    function closeWarehouseDocument() { closeWarehouseModal('warehouse-document-modal'); document.getElementById('warehouse-document-frame').src = 'about:blank'; }
    document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { closeWarehouseModal('warehouse-detail-modal'); closeWarehouseDocument(); } });
</script>
@endpush
